css:
@page { size: 80mm auto; margin: 0; }
.print-format { width: 72mm; padding: 2mm; font-size: 12px; font-family: monospace; }
.print-format table { width: 100%; border-collapse: collapse; }
.print-format .header { text-align: center; font-weight: bold; font-size: 14px; margin-bottom: 4mm; }
.print-format .section { margin-top: 2mm; margin-bottom: 2mm; }
.print-format .label { font-weight: bold; }
.print-format .item-row td { padding-top: 1mm; padding-bottom: 1mm; border-top: 1px dashed #ccc; }
.print-format .totals { margin-top: 2mm; padding-top: 2mm; border-top: 2px solid #000; }
.print-format .footer { text-align: center; margin-top: 4mm; padding-top: 2mm; border-top: 1px dashed #ccc; }
